/**
 * VendorAuctionsE — v52bx. Lists reverse auctions the vendor can join:
 * (a) every auction tied to a notice they already bid on, (b) explicit
 * admin invitations. Mounted at /vendor/auctions.
 */
import { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { Trophy } from "lucide-react";
import { reverseAuctionApi, showApiError } from "@/lib/api";
import VendorPortalChrome from "./VendorPortalChrome";

export default function VendorAuctionsE() {
  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    reverseAuctionApi.mine()
      .then((d) => setItems(d.items || []))
      .catch(showApiError)
      .finally(() => setLoading(false));
  }, []);

  return (
    <div className="pmc-vp" data-pmc-e-page="vendor-auctions-e">
      <VendorPortalChrome active="Reverse auctions">
        <div className="pmc-page">
          <div className="pmc-page__head">
            <h1 className="pmc-page__title">Reverse auctions</h1>
            <p className="pmc-page__lead">Live and upcoming auctions you can join. Click Enter to go to the auction room — your identity stays masked to competitors.</p>
          </div>
          <div className="pmc-panel" data-testid="va-list">
            <div className="pmc-panel__head"><h2>Open to you</h2></div>
            <div className="pmc-panel__body">
              {loading && <div style={{ padding: 16 }}>Loading…</div>}
              {!loading && items.length === 0 && (
                <div style={{ padding: 24, color: "var(--on-chrome-muted)" }}>
                  No reverse auctions right now. If PMC invites you, it will appear here.
                </div>
              )}
              {items.map((a) => (
                <div key={a.id} className="pmc-txn" data-testid={`va-row-${a.id}`}
                     style={{ display: "grid", gridTemplateColumns: "1fr auto", gap: 12, padding: 12, borderBottom: "1px solid rgba(15,59,46,.08)" }}>
                  <div>
                    <div style={{ fontWeight: 600, display: "flex", alignItems: "center", gap: 8 }}>
                      {a.title}
                      {/* v53c — trophy badge so a WON/awarded auction is
                          visible on the list without opening the room. */}
                      {a.status === "closed" && a.outcome === "won" && (
                        <span title={a.awarded_bid_id ? "Contract awarded to you" : "You won — awaiting award"}
                              data-testid={`va-trophy-${a.id}`}
                              style={{ display: "inline-flex", alignItems: "center", gap: 4,
                                       fontSize: 10, fontWeight: 700, letterSpacing: ".08em",
                                       textTransform: "uppercase", color: "#0f5132",
                                       background: "rgba(16,122,74,.12)",
                                       border: "1px solid rgba(16,122,74,.4)",
                                       borderRadius: 999, padding: "2px 8px" }}>
                          <Trophy size={11} strokeWidth={2.5} />
                          {a.awarded_bid_id ? "Contract awarded" : "You won"}
                        </span>
                      )}
                    </div>
                    <div style={{ fontSize: 12, color: "var(--on-chrome-muted)" }}>
                      {a.notice_ref} · {a.currency} · start {Number(a.starting_price || 0).toLocaleString()} → floor {Number(a.floor_price || 0).toLocaleString()}
                    </div>
                    <div style={{ fontSize: 11, marginTop: 4 }}>
                      <span className={`pmc-pill ${a.status === "live" ? "pmc-pill--success" : a.status === "draft" ? "pmc-pill--info" : "pmc-pill--warning"}`}>{a.status}</span>
                      {a.why && <span style={{ marginLeft: 8, color: "var(--on-chrome-muted)" }}>· {a.why}</span>}
                    </div>
                    {/* v53b — closed-auction outcome so the vendor immediately
                        knows whether they won and what happens next. */}
                    {a.status === "closed" && a.outcome === "won" && (
                      <div data-testid={`va-won-${a.id}`}
                           style={{ marginTop: 8, padding: "8px 12px", borderRadius: 6,
                                    background: "rgba(16,122,74,.08)", border: "1px solid rgba(16,122,74,.35)",
                                    fontSize: 12, color: "#0f5132" }}>
                        <strong>You won this auction</strong>
                        {a.winning_price != null && <> at {a.currency} {Number(a.winning_price).toLocaleString()}</>}.
                        {a.awarded_bid_id
                          ? <> The award is confirmed — your bid is moving through the approval pipeline. Track it under <Link to="/vendor/mybids">My bids</Link>.</>
                          : <> PMC will confirm the award shortly; you'll then receive the purchase order for e-signature.</>}
                      </div>
                    )}
                    {a.status === "closed" && a.outcome === "lost" && (
                      <div data-testid={`va-lost-${a.id}`}
                           style={{ marginTop: 8, fontSize: 12, color: "var(--on-chrome-muted)" }}>
                        This auction has closed — your bid was not the lowest this round.
                      </div>
                    )}
                    {/* v53i — invited but never registered. Show a distinct
                        reference so an invitee still has a trail of the
                        opportunity they were given, and is told it was
                        awarded to another bidder. */}
                    {a.status === "closed" && a.outcome === "not_participated" && (
                      <div data-testid={`va-notpart-${a.id}`}
                           style={{ marginTop: 8, padding: "8px 12px", borderRadius: 6,
                                    background: "rgba(148,163,184,.12)",
                                    border: "1px solid rgba(100,116,139,.35)",
                                    fontSize: 12, color: "var(--on-chrome-muted)" }}>
                        <strong>You were invited to this auction</strong> but did not register
                        before it closed. It has been awarded to another bidder.
                      </div>
                    )}
                  </div>
                  <div style={{ alignSelf: "center" }}>
                    <Link to={`/vendor/auction/${a.id}`} className="pmc-btn pmc-btn--primary pmc-btn--sm" data-testid={`va-enter-${a.id}`}>
                      {a.status === "live" ? "Enter" : "View details"}
                    </Link>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </VendorPortalChrome>
    </div>
  );
}
