import { useEffect, useState } from "react";
import { Link, useParams, useNavigate, useSearchParams } from "react-router-dom";
import { publicApi, adminApi, formatApiError, showApiError} from "@/lib/api";
import { useI18n } from "@/context/I18nContext";
import { useUiTheme } from "@/context/UiThemeContext";
import TopBar from "@/apps/shared/TopBar";
import Footer from "@/apps/shared/Footer";
import GatedDownload from "@/components/GatedDownload";
import NoticeQa from "./NoticeQa";
import { toast } from "sonner";

function DetailField({ label, value, mono = false }) {
  if (value == null || value === "") return null;
  return (
    <div className="border-t border-brand-navy/10 py-4">
      <div className="pmc-label">{label}</div>
      <div className={`mt-1 text-brand-navy ${mono ? "font-mono tabular-nums text-sm" : ""}`}>{value}</div>
    </div>
  );
}

export default function NoticeDetail() {
  const { t } = useI18n();
  const { isE } = useUiTheme();
  const { noticeRef } = useParams();
  const [searchParams] = useSearchParams();
  // v52cq — "Preview as bidder" from the admin draft list drops users here
  // with ?preview=1. We then fetch via adminApi (works for unpublished
  // drafts too) and render a banner so the admin knows this is not yet live.
  const previewMode = searchParams.get("preview") === "1";
  const navigate = useNavigate();
  const [notice, setNotice] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    const fetcher = previewMode
      ? adminApi.getNoticeAdmin(noticeRef)
      : publicApi.getNotice(noticeRef);
    fetcher
      .then((n) => !cancelled && setNotice(n))
      .catch((e) => {
        if (cancelled) return;
        showApiError(e);
        setTimeout(() => navigate(previewMode ? "/admin?tab=notices" : "/notices"), 1200);
      })
      .finally(() => !cancelled && setLoading(false));
    return () => { cancelled = true; };
  }, [noticeRef, navigate, previewMode]);

  useEffect(() => {
    if (notice) document.title = `${notice.title} — PMC Managers`;
    return () => { document.title = "PMC Managers · Global Tender Board"; };
  }, [notice]);

  const budget = notice?.budget_amount
    ? new Intl.NumberFormat("en-US", { style: "currency", currency: notice.budget_currency || "USD", maximumFractionDigits: 0 }).format(notice.budget_amount)
    : null;
  const deadline = notice?.submission_deadline ? new Date(notice.submission_deadline) : null;
  const preBid = notice?.pre_bid_meeting_date ? new Date(notice.pre_bid_meeting_date) : null;
  const publishedAt = notice?.published_at ? new Date(notice.published_at) : null;

  return (
    <div className="min-h-screen bg-brand-pale flex flex-col" data-ui={isE ? "e" : undefined}>
      <TopBar />

      {/* Option E — hero band (opt-in) with notice ref, chips, big title, KPI strip */}
      {isE && notice && (
        <section className="e-hero-band" data-testid="notice-detail-hero-e">
          <svg aria-hidden="true" fill="none" viewBox="0 0 1440 600" className="absolute right-0 top-0 h-full w-full pointer-events-none opacity-90" preserveAspectRatio="xMaxYMid slice">
            <circle stroke="rgba(210,180,106,0.20)" r="180" cy="300" cx="1220" />
            <circle stroke="rgba(210,180,106,0.14)" r="290" cy="300" cx="1220" />
            <circle stroke="rgba(210,180,106,0.09)" r="420" cy="300" cx="1220" />
            <circle stroke="rgba(210,180,106,0.05)" r="570" cy="300" cx="1220" />
          </svg>
          <div className="e-hero-inner">
            <nav className="e-hero-breadcrumb" aria-label="Breadcrumb">
              <Link to="/tenders/live">Live tenders</Link>
              <span className="e-sep" aria-hidden="true">·</span>
              <span>{notice.category || "General"}</span>
              <span className="e-sep" aria-hidden="true">·</span>
              <span className="e-crumb-current" aria-current="page">{notice.notice_ref}</span>
            </nav>
            {/* v52cq — admin draft preview banner so there is no doubt this
                is not visible to real vendors yet. */}
            {previewMode && (
              <div className="mt-6 border-2 border-amber-500 bg-amber-50 px-4 py-3 flex flex-wrap items-center gap-3"
                   data-testid="draft-preview-banner">
                <span className="font-mono text-[10px] uppercase tracking-widest bg-amber-500 text-white px-2 py-1">
                  DRAFT PREVIEW
                </span>
                <span className="text-sm text-amber-900 flex-1">
                  Showing the <strong>bidder view</strong> of this unpublished notice.
                  Vendors cannot see or bid on this yet — publish it from{" "}
                  <Link to="/admin?tab=notices" className="underline hover:text-amber-700">Admin → Notices</Link>.
                </span>
                {notice.is_published === false && (
                  <span className="text-[10px] uppercase tracking-widest border border-amber-700 text-amber-900 px-2 py-1">
                    is_published = false
                  </span>
                )}
              </div>
            )}
            <div className="mt-6 flex flex-wrap items-center gap-2.5">
              <span className="font-mono text-xs tracking-[0.12em] text-brand-gold uppercase mr-1">
                Notice {notice.notice_ref}
              </span>
              {deadline && (deadline - new Date()) < 1000*60*60*24*7 && (deadline - new Date()) > 0 && (
                <span className="e-chip e-chip-warn">
                  <span className="e-live-dot" /> Closing soon
                </span>
              )}
              {notice.document_type && (
                <span className="e-chip">{notice.document_type.toUpperCase()} · Open tender</span>
              )}
              {(notice.corrigenda?.length || 0) > 0 && (
                <span className="e-chip e-chip-live">
                  <span className="font-mono text-[11px] text-brand-gold">REV</span>
                  Corrigendum #{notice.corrigenda.length} in force
                </span>
              )}
            </div>
            <h1 className="mt-6 e-hero-title text-4xl md:text-5xl lg:text-[64px]" data-testid={`hero-title-${notice.notice_ref}`}>
              {notice.title}
            </h1>
            <div className="mt-4 text-[#D9D3BF] text-base md:text-lg">
              {notice.delivery_country ? `Issued for ${notice.delivery_country}` : "Public tender"}
              {publishedAt && ` · Published ${publishedAt.toISOString().slice(0,10)}`}
              {notice.created_by_email && ` · Posted by ${notice.created_by_email}`}
            </div>
          </div>
          <dl className="e-hero-kpi-strip">
            <div>
              <dt>Estimated value</dt>
              <dd>{budget || "—"}</dd>
            </div>
            <div>
              <dt>EMD</dt>
              <dd>
                {notice.emd_amount
                  ? new Intl.NumberFormat("en-US", { style: "currency", currency: notice.emd_currency || notice.budget_currency || "USD", maximumFractionDigits: 0 }).format(notice.emd_amount)
                  : "As per pack"}
              </dd>
            </div>
            <div>
              <dt>Tender fee</dt>
              <dd>{notice.tender_fee || "Nil"}</dd>
            </div>
            <div>
              <dt>Deadline</dt>
              <dd className="font-mono text-lg">{deadline ? deadline.toISOString().slice(0,10) : "—"}</dd>
            </div>
            <div>
              <dt>Pre-bid</dt>
              <dd className="font-mono text-lg">{preBid ? preBid.toISOString().slice(0,10) : "Nil"}</dd>
            </div>
            <div>
              <dt>Evaluation</dt>
              <dd>{notice.evaluation_method || "QCBS"}</dd>
            </div>
          </dl>
        </section>
      )}

      <main className="flex-1 max-w-7xl mx-auto w-full px-6 lg:px-10 py-10">
        <div className="flex items-center justify-between gap-4">
          <Link to="/notices" className="text-xs uppercase tracking-widest text-brand-navy/60 hover:text-brand-navy inline-flex items-center gap-2" data-testid="back-to-list">
            ← {t("notice.back_to_list")}
          </Link>
          {notice && (
            <button
              type="button"
              onClick={() => window.print()}
              data-testid="print-notice"
              className="px-4 py-2 text-[11px] font-semibold uppercase tracking-widest border border-brand-navy/20 text-brand-navy hover:bg-brand-navy/5"
            >
              Print / Save as PDF
            </button>
          )}
        </div>

        {loading && <div className="text-brand-navy/60 py-16 text-center">{t("common.loading")}</div>}

        {notice && (
          <div className="mt-6 grid gap-10 lg:grid-cols-[8fr_4fr] lg:gap-14 items-start">
            <article className="bg-white border border-brand-navy/10 p-8 lg:p-12" data-testid={`notice-detail-${notice.notice_ref}`}>
              <div className="flex flex-wrap items-baseline gap-3">
                <span className="pmc-pill-navy uppercase">{notice.document_type}</span>
                <span className="pmc-label text-brand-navy-soft">{notice.notice_ref}</span>
              </div>
              <h1 className="font-display text-3xl lg:text-4xl mt-4 leading-tight text-brand-navy">{notice.title}</h1>
              {(publishedAt || notice.created_by_email) && (
                <div className="mt-2 text-sm text-brand-navy/60" data-testid={`notice-posted-by-${notice.notice_ref}`}>
                  {publishedAt && `Published ${publishedAt.toISOString().slice(0, 10)}`}
                  {publishedAt && notice.created_by_email && " · "}
                  {notice.created_by_email && `Posted by ${notice.created_by_email}`}
                </div>
              )}

              <div className="mt-8 prose max-w-none">
                {isE && <span className="font-serif text-[40px] leading-none text-[#7A5F1E] float-left mr-3">I</span>}
                <div className="pmc-label">Scope of work</div>
                <p className="whitespace-pre-wrap text-brand-navy/85 text-[15px] leading-7 mt-2">{notice.description}</p>
              </div>

              {(notice.corrigenda?.length || 0) > 0 && (
                <div className="mt-6 border-2 border-amber-500 bg-amber-50 p-5"
                     data-testid="notice-corrigenda-banner">
                  <div className="flex items-center justify-between gap-3 flex-wrap">
                    <div className="text-amber-900 font-semibold uppercase tracking-widest text-xs">
                      ⚠ {notice.corrigenda.length} corrigend{notice.corrigenda.length === 1 ? "um" : "a"} · read before bidding
                    </div>
                  </div>
                  <ol className="mt-3 space-y-4">
                    {notice.corrigenda.map((c) => (
                      <li key={c.id} className="text-sm text-amber-950"
                          data-testid={`corr-pub-${c.corrigendum_no}`}>
                        <div className="flex items-baseline gap-3 flex-wrap">
                          <span className="font-semibold">
                            Corrigendum No. {c.corrigendum_no} · {c.title}
                          </span>
                          {/* v52bn — bidders see the date only; the issuing
                              admin's email stays internal (audit ledger). */}
                          <span className="text-[11px] font-mono text-amber-800/80"
                                data-testid={`corr-pub-date-${c.corrigendum_no}`}>
                            {(c.effective_from || c.published_at || "").slice(0, 10)}
                          </span>
                        </div>
                        <div className="text-amber-900/90 whitespace-pre-line mt-1">{c.summary}</div>
                        {c.new_submission_deadline && (
                          <div className="text-xs text-amber-800 mt-1">
                            New deadline: {c.new_submission_deadline?.slice(0, 16).replace("T", " ")}
                          </div>
                        )}
                        {/* v52bn — versioned field diff so bidders see exactly
                            what changed and why. */}
                        {(c.field_amendments || []).length > 0 && (
                          <div className="mt-2 overflow-x-auto border border-amber-400/60 bg-white/70"
                               data-testid={`corr-pub-table-${c.corrigendum_no}`}>
                            <table className="w-full text-xs">
                              <thead className="bg-amber-100/70 text-amber-950 uppercase tracking-widest text-[10px]">
                                <tr>
                                  <th className="text-left px-2 py-1.5">Field</th>
                                  <th className="text-left px-2 py-1.5">Before</th>
                                  <th className="text-left px-2 py-1.5">After</th>
                                  <th className="text-left px-2 py-1.5">Reason</th>
                                </tr>
                              </thead>
                              <tbody>
                                {c.field_amendments.map((a, idx) => (
                                  <tr key={idx} className="border-t border-amber-300/50 align-top">
                                    <td className="px-2 py-1.5 font-semibold text-amber-950">{a.field}</td>
                                    <td className="px-2 py-1.5 text-red-900 whitespace-pre-wrap break-words">{a.before || "—"}</td>
                                    <td className="px-2 py-1.5 text-emerald-900 whitespace-pre-wrap break-words">{a.after || "—"}</td>
                                    <td className="px-2 py-1.5 text-amber-900 whitespace-pre-wrap break-words">{a.note || "—"}</td>
                                  </tr>
                                ))}
                              </tbody>
                            </table>
                          </div>
                        )}
                      </li>
                    ))}
                  </ol>
                </div>
              )}

              {notice.primary_document && (
                <div className="mt-8" data-testid="notice-primary-document">
                  <div className="pmc-label">Tender / RFP / RFQ document</div>
                  {(notice.primary_document.size_bytes || 0) < 200 ? (
                    <div className="mt-2 border-2 border-amber-500 bg-amber-50 p-4 text-sm text-amber-900"
                         data-testid="notice-primary-placeholder">
                      <strong>⚠ Placeholder file detected</strong> — this notice was seeded during testing
                      and the real tender document has not been uploaded yet. Please contact{" "}
                      {notice.contact_email ? (
                        <a href={`mailto:${notice.contact_email}`} className="underline font-mono">
                          {notice.contact_email}
                        </a>
                      ) : "the procurement office"}
                      {" "}to request the official documents.
                    </div>
                  ) : (
                    <GatedDownload
                      href={notice.primary_document.url}
                      fileName={notice.primary_document.file_name}
                      sizeKb={Math.round((notice.primary_document.size_bytes || 0) / 1024)}
                      testid="notice-primary-download" />
                  )}
                </div>
              )}

              {notice.tender_template_id && (
                <div className="mt-8" data-testid="notice-composed-pdf">
                  <div className="pmc-label">Composed tender document</div>
                  <div className="mt-2 flex flex-wrap items-center gap-3">
                    <span className="text-[10px] uppercase tracking-widest text-brand-navy/60">Language:</span>
                    {["en", "ru", "kk"].map((lg) => (
                      <a key={lg}
                         href={`/api/v1/tender-templates/${notice.tender_template_id}/public/pdf?notice_ref=${encodeURIComponent(notice.notice_ref)}&lang=${lg}`}
                         data-testid={`notice-composed-download-${lg}`}
                         className={`inline-flex items-center gap-2 px-3 py-2 border text-[11px] uppercase tracking-widest ${lg === 'en' ? 'bg-brand-navy text-white border-brand-navy hover:bg-brand-navy-deep' : 'border-brand-navy/40 text-brand-navy hover:bg-brand-navy hover:text-white'}`}>
                        ⬇ PDF · {lg.toUpperCase()}
                      </a>
                    ))}
                    <a href={`/api/v1/tender-templates/${notice.tender_template_id}/public/zip?notice_ref=${encodeURIComponent(notice.notice_ref)}`}
                       data-testid="notice-composed-zip"
                       className="inline-flex items-center gap-2 px-3 py-2 text-[11px] uppercase tracking-widest border border-brand-navy text-brand-navy hover:bg-brand-navy hover:text-white">
                      🗂 all docs (.zip)
                    </a>
                  </div>
                  <div className="mt-1 text-[11px] text-brand-navy/50">
                    Rendered live from the Tender Builder — includes every annexure and template attachment.
                    Static labels are translated; bodies remain in the language the admin wrote them.
                  </div>
                </div>
              )}

              {notice.attachments?.length > 0 && (
                <div className="mt-8">
                  <div className="pmc-label">{t("notice.attachments")} ({notice.attachments.length})</div>
                  <ul className="mt-2 text-sm text-brand-navy-soft space-y-1">
                    {notice.attachments.map((a, i) => {
                      // v51au — public tender attachments must route through the
                      // new /uploads/public-files/ endpoint (xlsx #3, #8). The
                      // old URL required a signed-in user and bounced anonymous
                      // visitors to the sign-in screen. Attachment metadata
                      // carries { key, url, file_name } — we rebuild the URL
                      // ourselves to hit the public endpoint.
                      const publicUrl = a.key
                        ? `/api/v1/uploads/public-files/${a.key}?download=1`
                        : (a.url || "#");
                      const href = publicUrl;
                      const label = a.file_name || a.name || a.key || "attachment";
                      const sizeKb = a.size_bytes ? Math.round(a.size_bytes / 1024) : null;
                      return (
                        <li key={a.key || a.url || i} data-testid={`attachment-${i}`} className="flex">
                          <GatedDownload href={href} fileName={label} sizeKb={sizeKb}
                            testid={`attachment-download-${i}`} compact />
                        </li>
                      );
                    })}
                  </ul>
                </div>
              )}
            </article>

            <aside className="bg-white border border-brand-navy/10 p-6 lg:p-8 lg:sticky lg:top-6">
              <div className="pmc-label">Key details</div>
              <DetailField label={t("notice.category")} value={notice.category} />
              <DetailField label={t("notice.country")} value={notice.delivery_country} />
              <DetailField label={t("notice.budget")} value={budget} mono />
              <DetailField label={t("notice.submission_deadline")} value={deadline?.toISOString().replace("T", " ").slice(0, 16)} mono />
              <DetailField label={t("notice.pre_bid")} value={preBid?.toISOString().replace("T", " ").slice(0, 16)} mono />
              <DetailField label={t("notice.required_licenses")} value={notice.required_licenses?.join(", ")} />
              <DetailField label={t("notice.contact")} value={notice.contact_name} />
              <DetailField label="Contact email" value={notice.contact_email} mono />
              <DetailField label={t("notice.published_at")} value={publishedAt?.toISOString().slice(0, 10)} mono />

              <Link
                to="/register"
                data-testid="detail-cta-register"
                className="mt-8 block w-full text-center bg-brand-navy-soft text-white px-6 py-4 uppercase tracking-widest text-[0.8125rem] font-semibold hover:bg-brand-navy-soft/90 transition-colors"
              >
                {t("notice.register_to_bid")}
              </Link>
            </aside>
          </div>
        )}
        {notice && <NoticeQa noticeRef={notice.notice_ref} />}
      </main>
      <Footer />
    </div>
  );
}
